insert into fk_reim_itinerary (
    id, main_id, subsidy_id, traveler_id, traveler_no, traveler_name,
    departure_date, arrival_date, departure_city, departure_city_no,
    arriving_city, arriving_city_no, itinerary_instructions
) values (
    #{id}, #{mainId}, #{subsidyId}, #{travelerId}, #{travelerNo}, #{travelerName},
    #{departureDate}, #{arrivalDate}, #{departureCity}, #{departureCityNo},
    #{arrivingCity}, #{arrivingCityNo}, #{itineraryInstructions}
)
